/* 开场动画 — DOM烟花 + 喵小姐字体 */
@font-face {
  font-family: 'MiaoFont';
  src: url('/fonts/miao-subset.woff2') format('woff2'), url('/fonts/miao.ttf');
}

#kuri-preloader {
  position: fixed;
  top: 0; left: 0;
  width: 100%;
  height: 100vh;       /* 旧浏览器兜底 */
  height: 100dvh;      /* iOS Safari 15.4+, Chrome 108+: 动态视口，跟随地址栏 */
  z-index: 10000;
  background: #E8D7F9;
  overflow: hidden;
}

/* 烟花容器 */
#emote-rain {
  position: absolute;
  width: 100%; height: 100%;
}
#emote-rain img {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  will-change: transform, opacity;
  animation: burstParticle 2.5s ease-out forwards;
}
@keyframes burstParticle {
  0%   { transform: translate(-50%,-50%) translate(0px,0px) rotate(0deg) scale(1); opacity: 1; }
  80%  { opacity: 1; }
  100% { transform: translate(-50%,-50%) translate(var(--dx),var(--dy)) rotate(var(--rot)) scale(0.5); opacity: 0; }
}

/* 文字居中容器 */
.pl-center {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 10;
}

/* 标题 */
#pl-title {
  font-family: 'MiaoFont', sans-serif;
  font-size: clamp(2rem, 9vw, 4rem);
  color: #5b2c8a;
  text-shadow: 0 0 12px rgba(200,160,255,0.5), 0 0 30px rgba(180,130,255,0.3);
  visibility: hidden;
}
#pl-title .char {
  display: inline-block;
  visibility: visible;
  will-change: transform, opacity;
}

/* ── 移动端适配 ────────────────────────────── */
@media (max-width: 768px) {
  #emote-rain img {
    animation-duration: 2s;
  }
  #pl-title {
    font-size: clamp(1.6rem, 11vw, 2.8rem);
    text-shadow: 0 0 8px rgba(200,160,255,0.4), 0 0 20px rgba(180,130,255,0.25);
  }
}

@media (max-width: 400px) {
  #pl-title {
    font-size: clamp(1.4rem, 13vw, 2.2rem);
  }
}

/* ── 无障碍：减少动画 ──────────────────────── */
@media (prefers-reduced-motion: reduce) {
  #emote-rain img,
  #pl-title .char {
    animation: none;
    opacity: 1;
  }
  #pl-title .char {
    transform: translateY(0) scale(1) rotate(0deg);
  }
}

